BEGIN TRANSACTION;
CREATE TABLE "accounts_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "role" varchar(20) NOT NULL, "phone" varchar(10) NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "account_locked_until" datetime NULL, "failed_login_attempts" integer NOT NULL, "last_failed_login" datetime NULL, "last_login_ip" char(39) NULL, "last_login_user_agent" text NULL, "last_successful_login" datetime NULL, "email_verification_expiry" datetime NULL, "email_verification_otp" varchar(6) NULL, "email_verified" bool NOT NULL, "last_resend_time" datetime NULL, "login_otp" varchar(6) NULL, "login_otp_expiry" datetime NULL, "otp_attempts" integer NOT NULL, "password_reset_otp" varchar(6) NULL, "password_reset_otp_expiry" datetime NULL, "resend_count" integer NOT NULL, "account_locked" bool NOT NULL, "failed_attempts" integer NOT NULL, "lock_until" datetime NULL);
CREATE TABLE "accounts_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "appointments_appointment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL, "time_slot" varchar(10) NOT NULL, "status" varchar(20) NOT NULL, "reason" text NOT NULL, "rejection_reason" text NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "doctor_id" bigint NOT NULL REFERENCES "doctors_doctorprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "reminder_1h_sent" bool NOT NULL, "reminder_24h_sent" bool NOT NULL, "reminder_3h_sent" bool NOT NULL);
CREATE TABLE "appointments_prescription" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "medicines_text" text NOT NULL, "dosage_instructions" text NULL, "attached_file" varchar(100) NULL, "created_at" datetime NOT NULL, "appointment_id" bigint NOT NULL UNIQUE REFERENCES "appointments_appointment" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "appointments_specialization" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "description" text NULL, "icon" varchar(50) NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "backups_backuprecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "backup_name" varchar(255) NOT NULL UNIQUE, "backup_type" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "file_size" bigint NOT NULL, "storage_path" varchar(500) NOT NULL, "encrypted" bool NOT NULL, "checksum" varchar(64) NULL, "status" varchar(20) NOT NULL, "backup_duration" real NOT NULL, "notes" text NULL, "created_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "backups_backupscheduleconfig" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "frequency" varchar(20) NOT NULL, "backup_time" time NOT NULL, "retention_days" integer NOT NULL, "is_enabled" bool NOT NULL, "last_run" datetime NULL);
CREATE TABLE "backups_recoveryrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "restored_at" datetime NOT NULL, "recovery_status" varchar(20) NOT NULL, "recovery_duration" real NOT NULL, "notes" text NULL, "backup_id" bigint NOT NULL REFERENCES "backups_backuprecord" ("id") DEFERRABLE INITIALLY DEFERRED, "restored_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_auditlog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action" varchar(150) NOT NULL, "details" text NULL, "ip_address" char(39) NULL, "timestamp" datetime NOT NULL, "actor_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_notification" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "message" text NOT NULL, "notif_type" varchar(20) NOT NULL, "is_read" bool NOT NULL, "link" varchar(255) NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_review" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "rating" smallint unsigned NOT NULL CHECK ("rating" >= 0), "comment" text NOT NULL, "created_at" datetime NOT NULL, "doctor_id" bigint NOT NULL REFERENCES "doctors_doctorprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patientprofile" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "doctors_doctoravailability" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "weekday" integer NOT NULL, "start_time" time NOT NULL, "end_time" time NOT NULL, "doctor_id" bigint NOT NULL REFERENCES "doctors_doctorprofile" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "doctors_doctorprofile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "license_number" varchar(50) NOT NULL UNIQUE, "qualification" varchar(150) NOT NULL, "experience_years" integer unsigned NOT NULL CHECK ("experience_years" >= 0), "hospital_name" varchar(150) NOT NULL, "consultation_fee" decimal NOT NULL, "profile_photo" varchar(100) NULL, "is_approved" bool NOT NULL, "bio" text NULL, "created_at" datetime NOT NULL, "specialization_id" bigint NULL REFERENCES "appointments_specialization" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL UNIQUE REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "email_logs" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "recipient_email" varchar(254) NOT NULL, "recipient_type" varchar(10) NOT NULL, "email_type" varchar(30) NOT NULL, "subject" varchar(255) NOT NULL, "status" varchar(10) NOT NULL, "error_message" text NULL, "sent_at" datetime NOT NULL, "appointment_id" bigint NULL REFERENCES "appointments_appointment" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "patients_medicalrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(150) NOT NULL, "record_type" varchar(20) NOT NULL, "file" varchar(100) NOT NULL, "description" text NULL, "uploaded_at" datetime NOT NULL, "patient_id" bigint NOT NULL REFERENCES "patients_patientprofile" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "patients_medicalreport" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "report_name" varchar(100) NOT NULL, "report_category" varchar(30) NOT NULL, "description" text NULL, "file" varchar(100) NOT NULL, "file_size" bigint NOT NULL, "file_type" varchar(50) NOT NULL, "uploaded_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "review_status" varchar(20) NOT NULL, "doctor_notes" text NULL, "is_deleted" bool NOT NULL, "created_ip" char(39) NULL, "last_accessed" datetime NULL, "appointment_id" bigint NULL REFERENCES "appointments_appointment" ("id") DEFERRABLE INITIALLY DEFERRED, "doctor_id" bigint NULL REFERENCES "doctors_doctorprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patientprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "patients_patientprofile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "dob" date NULL, "gender" varchar(10) NOT NULL, "blood_group" varchar(5) NULL, "height_cm" real NOT NULL, "weight_kg" real NOT NULL, "address" text NULL, "emergency_contact_name" varchar(100) NULL, "emergency_contact_phone" varchar(15) NULL, "chronic_conditions" text NULL, "profile_photo" varchar(100) NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "payments_invoice" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "invoice_number" varchar(50) NOT NULL UNIQUE, "invoice_file" varchar(100) NOT NULL, "generated_at" datetime NOT NULL, "payment_id" bigint NOT NULL UNIQUE REFERENCES "payments_payment" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "payments_payment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "payment_id" varchar(50) NOT NULL UNIQUE, "transaction_id" varchar(50) NOT NULL UNIQUE, "amount" decimal NOT NULL, "platform_fee" decimal NOT NULL, "tax" decimal NOT NULL, "discount" decimal NOT NULL, "total_amount" decimal NOT NULL, "payment_method" varchar(30) NOT NULL, "payment_status" varchar(20) NOT NULL, "masked_payment_reference" varchar(100) NULL, "invoice_number" varchar(50) NOT NULL UNIQUE, "invoice_pdf" varchar(100) NULL, "payment_date" datetime NULL, "remarks" text NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "appointment_id" bigint NOT NULL UNIQUE REFERENCES "appointments_appointment" ("id") DEFERRABLE INITIALLY DEFERRED, "doctor_id" bigint NOT NULL REFERENCES "doctors_doctorprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "card_type" varchar(30) NULL, "last_four_digits" varchar(4) NULL);
CREATE TABLE "payments_refund" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "refund_id" varchar(50) NOT NULL UNIQUE, "refund_amount" decimal NOT NULL, "refund_reason" text NOT NULL, "refund_status" varchar(20) NOT NULL, "processed_at" datetime NULL, "created_at" datetime NOT NULL, "payment_id" bigint NOT NULL REFERENCES "payments_payment" ("id") DEFERRABLE INITIALLY DEFERRED, "processed_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "predictions_riskassessment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "age" integer NOT NULL, "gender" varchar(15) NOT NULL, "systolic_bp" integer NOT NULL, "diastolic_bp" integer NOT NULL, "fasting_sugar" real NOT NULL, "postprandial_sugar" real NOT NULL, "total_cholesterol" real NOT NULL, "hdl_cholesterol" real NOT NULL, "ldl_cholesterol" real NOT NULL, "height_cm" real NOT NULL, "weight_kg" real NOT NULL, "bmi" real NOT NULL, "smoking_status" varchar(20) NOT NULL, "alcohol_consumption" varchar(20) NOT NULL, "physical_activity" varchar(20) NOT NULL, "family_history_text" text NULL, "chronic_conditions_text" text NULL, "symptoms_text" text NULL, "computed_score" integer NOT NULL, "computed_level" varchar(10) NOT NULL, "heart_score" integer NOT NULL, "diabetes_score" integer NOT NULL, "hypertension_score" integer NOT NULL, "precautions_json" text NULL, "doctor_override_level" varchar(10) NULL, "doctor_notes" text NULL, "created_at" datetime NOT NULL, "appointment_id" bigint NULL REFERENCES "appointments_appointment" ("id") DEFERRABLE INITIALLY DEFERRED, "doctor_id" bigint NULL REFERENCES "doctors_doctorprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patientprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "body_temperature" real NULL, "heart_rate" integer NULL, "spo2_percentage" real NULL);
CREATE TABLE "prescriptions_prescription" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "prescription_number" varchar(50) NOT NULL UNIQUE, "diagnosis" varchar(500) NOT NULL, "symptoms" text NULL, "clinical_notes" text NULL, "follow_up_date" date NULL, "doctor_signature" varchar(100) NULL, "prescription_status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "appointment_id" bigint NULL REFERENCES "appointments_appointment" ("id") DEFERRABLE INITIALLY DEFERRED, "created_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "doctor_id" bigint NOT NULL REFERENCES "doctors_doctorprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "updated_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);

