CREATE TABLE "prescriptions_prescriptionmedicine" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "medicine_name" varchar(200) NOT NULL, "medicine_type" varchar(50) NOT NULL, "strength" varchar(50) NOT NULL, "dosage" varchar(100) NOT NULL, "frequency" varchar(100) NOT NULL, "morning" bool NOT NULL, "afternoon" bool NOT NULL, "night" bool NOT NULL, "duration" varchar(50) NOT NULL, "meal_instruction" varchar(50) NOT NULL, "quantity" varchar(50) NOT NULL, "notes" text NULL, "prescription_id" bigint NOT NULL REFERENCES "prescriptions_prescription" ("id") DEFERRABLE INITIALLY DEFERRED);
